package semver

import (
	"encoding/json"
	"os"
	"sort"
	"strings"
	"testing"
)

// The corpus is generated by npm's own semver (7.7.4, bundled with npm 10)
// from a fixed list of tricky ranges plus 400 randomly generated ones.
// Regenerate with the script in CONTRIBUTING.md.
type corpus struct {
	Versions []string `json:"versions"`
	Order    []string `json:"order"`
	Cases    []struct {
		Range     string   `json:"range"`
		Satisfies []string `json:"satisfies"`
	} `json:"cases"`
	Invalid []string `json:"invalid"`
}

func loadCorpus(t *testing.T) corpus {
	b, err := os.ReadFile("testdata/semver_corpus.json")
	if err != nil {
		t.Fatal(err)
	}
	var c corpus
	if err := json.Unmarshal(b, &c); err != nil {
		t.Fatal(err)
	}
	return c
}

func TestMatchesNPMSatisfies(t *testing.T) {
	c := loadCorpus(t)
	vs := make([]Version, len(c.Versions))
	for i, s := range c.Versions {
		v, err := Parse(s)
		if err != nil {
			t.Fatalf("parse %s: %v", s, err)
		}
		vs[i] = v
	}
	fails := 0
	for _, tc := range c.Cases {
		r, err := ParseRange(tc.Range)
		if err != nil {
			t.Errorf("npm accepts %q, we reject it: %v", tc.Range, err)
			fails++
			continue
		}
		want := map[string]bool{}
		for _, s := range tc.Satisfies {
			want[s] = true
		}
		var got, missing, extra []string
		for i, v := range vs {
			ok := r.Satisfies(v)
			if ok {
				got = append(got, c.Versions[i])
			}
			if ok && !want[c.Versions[i]] {
				extra = append(extra, c.Versions[i])
			}
			if !ok && want[c.Versions[i]] {
				missing = append(missing, c.Versions[i])
			}
		}
		if len(missing)+len(extra) > 0 {
			fails++
			t.Errorf("%q: missing %v, extra %v", tc.Range, missing, extra)
		}
	}
	t.Logf("%d ranges compared with npm semver, %d mismatches", len(c.Cases), fails)
}

func TestRejectsWhatNPMRejects(t *testing.T) {
	c := loadCorpus(t)
	for _, r := range c.Invalid {
		if _, err := ParseRange(r); err == nil {
			// A range npm rejects must never be treated as valid: that would
			// pick a version npm itself would refuse to install.
			t.Errorf("npm rejects %q, we accepted it", r)
		}
	}
}

func TestOrderMatchesNPM(t *testing.T) {
	c := loadCorpus(t)
	vs := make([]Version, len(c.Versions))
	for i, s := range c.Versions {
		vs[i], _ = Parse(s)
	}
	sort.Slice(vs, func(i, j int) bool { return Compare(vs[i], vs[j]) < 0 })
	got := make([]string, len(vs))
	for i, v := range vs {
		got[i] = v.String()
	}
	if strings.Join(got, " ") != strings.Join(c.Order, " ") {
		t.Fatalf("order differs\n got  %v\n want %v", got, c.Order)
	}
}

func FuzzParseRange(f *testing.F) {
	for _, s := range []string{"^1.2.3", "1.x || >=2 <3", "1.2 - 2", "~>1.2", ">= 1.2.3-beta.1"} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, s string) {
		r, err := ParseRange(s)
		if err == nil {
			v, _ := Parse("1.2.3")
			_ = r.Satisfies(v)
		}
	})
}
